 "content": "def transform(grid):
    """Complete the sparser of two translated copies; mark added cells with 1."""
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [c for c, n in counts.items() if c != bg]
    if not colors:
        return [row[:] for row in grid]
    fg = max(colors, key=lambda c: counts[c])

    # The two copies occupy separated contiguous bands of non-background rows.
    active = [any(v != bg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return [row[:] for row in grid]
    # Task instances contain two repeated motifs; use the first and last bands.
    top0, top1 = bands[0]
    bot0, bot1 = bands[-1]
    ht, hb = top1 - top0, bot1 - bot0
    if ht != hb:
        return [row[:] for row in grid]

    # Find their horizontal translation by maximum pixel agreement on overlap.
    best_dx, best_score, best_overlap = 0, -1, -1
    for dx in range(-(w - 1), w):
        score = overlap = 0
        for k in range(ht):
            for c in range(w):
                d = c + dx
                if 0 <= d < w:
                    overlap += 1
                    score += grid[top0 + k][c] == grid[bot0 + k][d]
        if (score, overlap) > (best_score, best_overlap):
            best_dx, best_score, best_overlap = dx, score, overlap

    top_n = sum(grid[r][c] == fg for r in range(top0, top1) for c in range(w))
    bot_n = sum(grid[r][c] == fg for r in range(bot0, bot1) for c in range(w))
    out = [row[:] for row in grid]
    # Copy only into the less complete motif, preserving existing motif cells.
    if top_n >= bot_n:
        # Top motif is source; translated top coordinates map into bottom.
        for k in range(ht):
            for c in range(w):
                d = c + best_dx
                if 0 <= d < w and grid[top0 + k][c] == fg and grid[bot0 + k][d] == bg:
                    out[bot0 + k][d] = 1
    else:
        # Bottom motif is source; invert the translation.
        for k in range(ht):
            for d in range(w):
                c = d - best_dx
                if 0 <= c < w and grid[bot0 + k][d] == fg and grid[top0 + k][c] == bg:
                    out[top0 + k][c] = 1
    return out
"
