{
 "content": "def transform(grid):
    """Mark the continuation of the incomplete one of two repeated motifs."""
    from collections import Counter

    h = len(grid)
    w = max(map(len, grid))
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    a = [[x for x in row] + [bg] * (w - len(row)) for row in grid]
    colors = [x for row in a for x in row if x != bg]
    if not colors:
        return a
    fg = Counter(colors).most_common(1)[0][0]

    active = [any(x != bg for x in row) for row in a]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return a
    top0, top1 = bands[0]
    bot0, bot1 = bands[-1]
    if top1 - top0 != bot1 - bot0:
        return a
    ht = top1 - top0

    # Find the translation that best aligns foreground pixels, with background ignored.
    best_dx, best_score = 0, -1.0
    for dx in range(-(w - 1), w):
        matches = overlap = 0
        for k in range(ht):
            for c in range(w):
                d = c + dx
                if 0 <= d < w and (a[top0 + k][c] == fg or a[bot0 + k][d] == fg):
                    overlap += 1
                    matches += a[top0 + k][c] == a[bot0 + k][d]
        score = matches / overlap if overlap else -1.0
        if score > best_score:
            best_dx, best_score = dx, score

    top_n = sum(a[r][c] == fg for r in range(top0, top1) for c in range(w))
    bot_n = sum(a[r][c] == fg for r in range(bot0, bot1) for c in range(w))
    out = [row[:] for row in a]
    if top_n >= bot_n:
        # Lower motif shifted by dx is the more complete source: map it back to top.
        for k in range(ht):
            for d in range(w):
                c = d - best_dx
                if 0 <= c < w and a[bot0 + k][d] == fg and a[top0 + k][c] == bg:
                    out[top0 + k][c] = 1
    else:
        for k in range(ht):
            for c in range(w):
                d = c + best_dx
                if 0 <= d < w and a[top0 + k][c] == fg and a[bot0 + k][d] == bg:
                    out[bot0 + k][d] = 1
    return out
